import React from 'react';

export default function Visualizer({
  input = { array: [], target: undefined },
  currentStep,
  isRunning,
  stepIdx,
  ...props
}) {
  const arr = Array.isArray(input?.array) ? input.array : [];
  const target = input?.target;
  const idx = currentStep?.index;
  const found = currentStep?.found;
  const done = currentStep?.done;

  return (
    <div className="linear-viz-root" style={{ padding: 32, textAlign: 'center' }}>
      <div style={{ fontSize: 18, marginBottom: 18 }}>
        {typeof target !== 'undefined' && <>
          Searching for <b style={{ color: '#1e90ff' }}>{target}</b> in array
        </>}
      </div>
      <div className="linear-array-bar" style={{ display: 'flex', justifyContent: 'center', gap: 8, marginBottom: 24 }}>
        {arr.map((val, i) => {
          let bg = '#e6ecfa';
          let border = '#b6c6e3';
          let color = '#1a2540';
          if (idx === i && !done) {
            bg = '#ffe066';
            border = '#e6b800';
            color = '#1a2540';
          }
          if (done && found && idx === i) {
            bg = '#7be495';
            border = '#1fa463';
            color = '#1a2540';
          }
          return (
            <div key={i} style={{
              minWidth: 44, minHeight: 64, background: bg, border: `2px solid ${border}`,
              borderRadius: 10, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
              fontSize: 22, fontWeight: 700, color, position: 'relative', boxShadow: idx === i ? '0 2px 12px #ffe06655' : undefined
            }}>
              {val}
              {idx === i && !done && (
                <div style={{ position: 'absolute', top: -28, left: '50%', transform: 'translateX(-50%)', fontSize: 16, color: '#e6b800' }}>
                  ▼
                </div>
              )}
              {done && found && idx === i && (
                <div style={{ position: 'absolute', top: -28, left: '50%', transform: 'translateX(-50%)', fontSize: 16, color: '#1fa463' }}>
                  ✓
                </div>
              )}
            </div>
          );
        })}
      </div>
      <div style={{ minHeight: 32, fontSize: 16, color: done && !found ? '#e74c3c' : '#4a6080', marginBottom: 12 }}>
        {currentStep?.msg || 'Press Run to start'}
      </div>
      {done && (
        <div style={{ fontSize: 18, fontWeight: 600, color: found ? '#1fa463' : '#e74c3c' }}>
          {found ? `Found ${target} at index ${idx}` : `Target ${target} not found`}
        </div>
      )}
    </div>
  );
}
